using System.Text;using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Reports;[Authorize]public sealed class IndexModel(MediStockDbContext db):PageModel{[BindProperty(SupportsGet=true)]public string ReportType{get;set;}="Sales";[BindProperty(SupportsGet=true)]public DateTime From{get;set;}=DateTime.UtcNow.AddMonths(-1);[BindProperty(SupportsGet=true)]public DateTime To{get;set;}=DateTime.UtcNow;public IReadOnlyList<string>Headers{get;private set;}=[];public IReadOnlyList<IReadOnlyList<string>>Rows{get;private set;}=[];
public async Task OnGetAsync(){await LoadAsync();}
public async Task<IActionResult>OnPostCsvAsync(){await LoadAsync();var sb=new StringBuilder();sb.AppendLine(string.Join(",",Headers.Select(Csv)));foreach(var row in Rows)sb.AppendLine(string.Join(",",row.Select(Csv)));return File(Encoding.UTF8.GetBytes(sb.ToString()),"text/csv",$"{ReportType}-report-{DateTime.UtcNow:yyyyMMdd}.csv");}
private async Task LoadAsync(){var from=From.Date;var to=To.Date.AddDays(1);if(ReportType=="Stock"){Headers=["Medicine","Batch","Quantity","Expiry","Supplier"];Rows=(await db.StockBatches.AsNoTracking().OrderBy(x=>x.Medicine.Name).Select(x=>new[]{x.Medicine.Name,x.BatchNumber,x.Quantity.ToString(),x.ExpiryDate.ToString("yyyy-MM-dd"),x.Supplier.Name}).ToListAsync()).Select(x=>(IReadOnlyList<string>)x).ToList();}else if(ReportType=="Expiry"){Headers=["Medicine","Batch","Quantity","Expiry","Status"];var today=DateTime.UtcNow.Date;var cutoff=today.AddDays(30);Rows=(await db.StockBatches.AsNoTracking().Where(x=>x.ExpiryDate>=from&&x.ExpiryDate<to).OrderBy(x=>x.ExpiryDate).Select(x=>new[]{x.Medicine.Name,x.BatchNumber,x.Quantity.ToString(),x.ExpiryDate.ToString("yyyy-MM-dd"),x.ExpiryDate<today?"Expired":x.ExpiryDate<=cutoff?"Expiring soon":"Usable"}).ToListAsync()).Select(x=>(IReadOnlyList<string>)x).ToList();}else if(ReportType=="Supplier"){Headers=["Supplier","Contact","Phone","Email","Active"];Rows=(await db.Suppliers.AsNoTracking().OrderBy(x=>x.Name).Select(x=>new[]{x.Name,x.ContactPerson??"",x.Phone,x.Email??"",x.IsActive?"Yes":"No"}).ToListAsync()).Select(x=>(IReadOnlyList<string>)x).ToList();}else{Headers=["Invoice","Date","Medicine","Quantity","Total","Payment","Status"];Rows=(await db.SaleItems.AsNoTracking().Include(x=>x.Sale).Include(x=>x.Medicine).Where(x=>x.Sale.SoldAtUtc>=from&&x.Sale.SoldAtUtc<to).OrderByDescending(x=>x.Sale.SoldAtUtc).Select(x=>new[]{x.Sale.InvoiceNumber,x.Sale.SoldAtUtc.ToString("yyyy-MM-dd"),x.Medicine.Name,x.Quantity.ToString(),x.LineTotal.ToString("0.00"),x.Sale.PaymentMethod,x.Sale.Status}).ToListAsync()).Select(x=>(IReadOnlyList<string>)x).ToList();}}
private static string Csv(string value){value=value.Replace("\"","\"\"");return value.Contains(',')||value.Contains('"')||value.Contains('\n')?$"\"{value}\"":value;}
}
